    printf("%d\n", getFront(q));

    // Remove the front element.
    dequeue(q);

    // Get the new front element.
    printf("%d\n", getFront(q));

    // Get the rear element.
    printf("%d\n", getRear(q));

    // Insert another element.
    enqueue(q, 40);

    return 0;
}


